import{_ as a,c as t,o as e,a3 as i}from"./chunks/framework.C5U8cnJv.js";const p="/xhh-blog/assets/image-7.BQnaoqKe.png",r="/xhh-blog/assets/image-3.b1-8UuXE.png",l="/xhh-blog/assets/image-2.Cl8AS1HH.png",o="/xhh-blog/assets/image-5.DTAbKJm2.png",n="/xhh-blog/assets/image-4.CI8Apfey.png",s="/xhh-blog/assets/image-1.CC71Ogak.png",h="/xhh-blog/assets/image.Dp4VGbyC.png",d="/xhh-blog/assets/image-6.DCg2Heg-.png",u="/xhh-blog/assets/image-8.BbUaxRIb.png",c="/xhh-blog/assets/image-9.BNSw7TcP.png",C=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"technology/uni-app/uni-app.md","filePath":"technology/uni-app/uni-app.md"}'),g={name:"technology/uni-app/uni-app.md"},m=i('<h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="https://uniapp.dcloud.net.cn/" target="_blank" rel="noreferrer">uni-app</a></li><li><a href="https://doc.dcloud.net.cn/uni-app-x/" target="_blank" rel="noreferrer">uni-app x</a></li><li><a href="https://www.dcloud.io/hbuilderx.html" target="_blank" rel="noreferrer">HbuilderX</a></li><li><a href="https://dev.dcloud.net.cn/pages/app/list" target="_blank" rel="noreferrer">开发者后台</a></li></ul><h2 id="新建项目" tabindex="-1">新建项目 <a class="header-anchor" href="#新建项目" aria-label="Permalink to &quot;新建项目&quot;">​</a></h2><p><img src="'+p+'" alt="alt text"></p><h3 id="uni-app-和-uni-app-x-区别" tabindex="-1">uni-app 和 uni-app X 区别： <a class="header-anchor" href="#uni-app-和-uni-app-x-区别" aria-label="Permalink to &quot;uni-app 和 uni-app X 区别：&quot;">​</a></h3><ul><li><strong>uni-app（老版）</strong></li></ul><p>App 端：WebView/Weex 渲染，JS 代码跑在 V8/JSC 引擎，靠<strong>JSBridge</strong>和原生通信，属于 Web 套壳 App； 页面文件：<code>.vue</code>，Vue2/Vue3 都支持。</p><ul><li><strong>uni-app X（新版）</strong></li></ul><p>App 端：<strong>UVue 原生渲染</strong>，无 JS 引擎，逻辑用<strong>UTS 强类型语言</strong>直接编译成 Kotlin（Android）、Swift（iOS）、ArkTS（鸿蒙），真正原生 App； 页面文件：<code>.uvue</code>后缀，仅兼容</p><h3 id="新建-uni-app-项目和-5-app-项目区别" tabindex="-1">新建 uni-app 项目和 5+App 项目区别： <a class="header-anchor" href="#新建-uni-app-项目和-5-app-项目区别" aria-label="Permalink to &quot;新建 uni-app 项目和 5+App 项目区别：&quot;">​</a></h3><ul><li>技术栈‌：uni-app 强制使用 ‌Vue.js‌ (.vue 组件)；5+App 使用传统 ‌HTML+CSS+JS‌ (.html 入口)。</li><li>API 调用‌：uni-app 主用 uni.xxx 通用 API（底层兼容 5+）；5+App 直接调用 plus.xxx 原生 API。</li><li>跨端能力‌：uni-app 一套代码编译至 ‌iOS/Android/H5/多端小程序‌；5+App ‌仅能打包为 App‌。</li><li>发布方式：uni-app 可一键发布为 H5、小程序、App 等；5+App 一般用于打包生成 Android/iOS 原生 App 包。</li></ul><h2 id="运行" tabindex="-1">运行 <a class="header-anchor" href="#运行" aria-label="Permalink to &quot;运行&quot;">​</a></h2><h3 id="运行到浏览器" tabindex="-1">运行到浏览器 <a class="header-anchor" href="#运行到浏览器" aria-label="Permalink to &quot;运行到浏览器&quot;">​</a></h3><p>运行 - 运行到浏览器</p><h3 id="运行到微信小程序" tabindex="-1">运行到微信小程序 <a class="header-anchor" href="#运行到微信小程序" aria-label="Permalink to &quot;运行到微信小程序&quot;">​</a></h3><p>运行 - 运行到小程序模拟器 - 微信开发者工具</p><h3 id="运行到android模拟器" tabindex="-1">运行到Android模拟器 <a class="header-anchor" href="#运行到android模拟器" aria-label="Permalink to &quot;运行到Android模拟器&quot;">​</a></h3><ol><li><p>下载Android Studio</p></li><li><p>创建模拟器 (Virtual Device Manager)，运行模拟器</p></li></ol><p><img src="'+r+'" alt="alt text"></p><ol start="3"><li>HBuilderX - 运行 - 运行到手机或模拟器 - 运行到Android App基座（先安装App真机运行插件，才有这个选项）</li></ol><p><img src="'+l+'" alt="alt text"></p><h3 id="运行到ios模拟器" tabindex="-1">运行到iOS模拟器 <a class="header-anchor" href="#运行到ios模拟器" aria-label="Permalink to &quot;运行到iOS模拟器&quot;">​</a></h3><p><a href="https://uniapp.dcloud.net.cn/tutorial/run/installSimulator.html#ios" target="_blank" rel="noreferrer">https://uniapp.dcloud.net.cn/tutorial/run/installSimulator.html#ios</a></p><h3 id="运行到ios真机" tabindex="-1">运行到iOS真机 <a class="header-anchor" href="#运行到ios真机" aria-label="Permalink to &quot;运行到iOS真机&quot;">​</a></h3><ol><li><p>安装itunes连接真机</p></li><li><p>制作自定义基座</p></li></ol><p>运行 - 运行到手机或模拟器 - 制作自定义调试基座 - 选择iOS(ipa包)</p><p><img src="'+o+'" alt="alt text"></p><ol start="3"><li>HBuilderX - 运行 - 运行到手机或模拟器 - 运行到iOS App基座</li></ol><p><img src="'+n+'" alt="alt text"></p><p>选中上一步骤生成的基座</p><h3 id="运行到android真机" tabindex="-1">运行到Android真机 <a class="header-anchor" href="#运行到android真机" aria-label="Permalink to &quot;运行到Android真机&quot;">​</a></h3><p><a href="https://uniapp.dcloud.net.cn/tutorial/run/run-app.html" target="_blank" rel="noreferrer">https://uniapp.dcloud.net.cn/tutorial/run/run-app.html</a></p><h2 id="发行" tabindex="-1">发行 <a class="header-anchor" href="#发行" aria-label="Permalink to &quot;发行&quot;">​</a></h2><h3 id="发布为h5" tabindex="-1">发布为h5 <a class="header-anchor" href="#发布为h5" aria-label="Permalink to &quot;发布为h5&quot;">​</a></h3><p>发行 - 网站-PC Web或 手机 H5 打包文件目录：unpackage\\dist\\build\\web</p><h3 id="发布微信小程序" tabindex="-1">发布微信小程序 <a class="header-anchor" href="#发布微信小程序" aria-label="Permalink to &quot;发布微信小程序&quot;">​</a></h3><ol><li><p>配置微信开发者工具路径（工具-设置）</p><p><img src="'+s+'" alt="alt text"></p></li><li><p>微信小程序开启服务端口</p><p><img src="'+h+'" alt="alt text"></p></li><li><p>(HBuilderX)mainfest.json -&gt; 微信小程序配置 -&gt; 填写AppId</p></li><li><p>(HBuilderX)发行 - 小程序-微信</p></li><li><p>微信开发者工具 “上传”</p></li></ol><h3 id="android云打包" tabindex="-1">Android云打包 <a class="header-anchor" href="#android云打包" aria-label="Permalink to &quot;Android云打包&quot;">​</a></h3><p>发行 =&gt; 原生App云打包</p><p>使用云端证书：</p><p><img src="'+d+'" alt="alt text"></p><p>使用自有证书：</p><p>开发者后台</p><p><img src="'+u+'" alt="alt text"></p><h3 id="ios云打包" tabindex="-1">iOS云打包 <a class="header-anchor" href="#ios云打包" aria-label="Permalink to &quot;iOS云打包&quot;">​</a></h3><p><a href="https://juejin.cn/post/7392535991973511219?searchId=20260811112141318A43FE6558DCBCB2C8" target="_blank" rel="noreferrer">https://juejin.cn/post/7392535991973511219?searchId=20260811112141318A43FE6558DCBCB2C8</a></p><p><img src="'+c+'" alt="alt text"></p>',47),b=[m];function _(x,A,f,q,S,k){return e(),t("div",null,b)}const B=a(g,[["render",_]]);export{C as __pageData,B as default};
